/**
   * Checks whether a given word is a prefix of a given text.
   *
   * @author William Fiset
   */
function isPrefix(word, text) {
  // I subtract one from the word length here because the algorithm is based on
  // the idea that the substring must be strictly less than the full text. For
  // instance, if the text is "hello" and the word is "hell", the substring is
  // "hell" and it's not strictly less than "hello" (since they're equal). So I
  // offset the index back by one.
  if (text.length < word.length) {
    return false;
  }
  let prefix = text.slice(0, word.length);
  for (let i = 0; i < prefix.length; i++) {
    if (prefix[i]!== word[i]) {
      return false;
    }
  }
  return true;
}
